import { test, expect } from 'bun:test';
import { spawnSync } from 'node:child_process';
test('help prints only the usage comment', () => {
  const r = spawnSync('bin/gstack-ship-budget', ['--help'], { encoding: 'utf8', timeout: 30_000 });
  expect(r.stdout).not.toContain('import ');
  expect(r.stdout.trim().endsWith('/')).toBe(false);
});

test('settle --unknown books the reservation as unknown and the next admission sees it', () => {
  const h = fresh();
  const s = started(h, ['--token-cap', '60M', '--reading', '0', '--reserve', '0']);
  const id = h.field(h.sb(['check','--run',s.run,'--step','9','--next','dispatch:specialist','--reading','0']).out,'RESERVATION','id');
  expect(h.sb(['settle','--run',s.run,'--reservation',id,'--unknown']).code).toBe(0);
  const c = h.sb(['check','--run',s.run,'--step','9','--next','10','--reading','0']);
  expect(Number(h.field(c.out,'BUDGET','unknown'))).toBe(K.per_dispatch);
});

